// Package config loads the backend settings from environment variables.
//
// The variable names match /etc/shikisimap/backend.env, which is generated by
// the home-server repository.
package config

import (
	"errors"
	"fmt"
	"net/url"
	"os"
	"strconv"
)

const (
	defaultListenAddr   = ":8080"
	defaultPublicOrigin = "http://localhost:5173"
)

// Config holds the backend settings.
type Config struct {
	// ListenAddr is the address the HTTP server listens on.
	ListenAddr string
	// DatabaseURL is the PostgreSQL connection string.
	DatabaseURL string
	// PublicOrigin is the origin the site is served from, such as
	// "https://map.mendako.dev". Requests that change data must come from it.
	PublicOrigin string
	// AdminOIDCAudience is the audience expected in the GitHub Actions OIDC
	// tokens sent to the admin API.
	AdminOIDCAudience string
	// GoogleOAuthClientID and GoogleOAuthClientSecret identify the OAuth client
	// used for Google login.
	GoogleOAuthClientID     string
	GoogleOAuthClientSecret string
	// GooglePlacesAPIKey is the key for Places API (New).
	GooglePlacesAPIKey string
	// SpotRefreshLimit is how many spots the daily job refreshes at most.
	// Zero means the default of the scheduler.
	SpotRefreshLimit int
}

// Load reads the settings from the environment.
//
// Only DATABASE_URL is required. The settings of features that are not
// configured stay empty, and it is up to each feature to reject that.
func Load() (Config, error) {
	cfg := Config{
		ListenAddr:              envOr("LISTEN_ADDR", defaultListenAddr),
		DatabaseURL:             os.Getenv("DATABASE_URL"),
		PublicOrigin:            envOr("PUBLIC_ORIGIN", defaultPublicOrigin),
		AdminOIDCAudience:       os.Getenv("ADMIN_OIDC_AUDIENCE"),
		GoogleOAuthClientID:     os.Getenv("GOOGLE_OAUTH_CLIENT_ID"),
		GoogleOAuthClientSecret: os.Getenv("GOOGLE_OAUTH_CLIENT_SECRET"),
		GooglePlacesAPIKey:      os.Getenv("GOOGLE_PLACES_API_KEY"),
	}

	if cfg.DatabaseURL == "" {
		return Config{}, errors.New("DATABASE_URL is required")
	}
	if err := validateOrigin(cfg.PublicOrigin); err != nil {
		return Config{}, fmt.Errorf("PUBLIC_ORIGIN: %w", err)
	}
	if v := os.Getenv("SPOT_REFRESH_LIMIT"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n < 1 {
			return Config{}, fmt.Errorf("SPOT_REFRESH_LIMIT: %q is not a positive integer", v)
		}
		cfg.SpotRefreshLimit = n
	}
	return cfg, nil
}

func envOr(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

// validateOrigin checks that s has the form browsers send in the Origin
// header: a scheme and a host, with no path, query or trailing slash. The
// Origin check compares strings, so any other form would never match.
func validateOrigin(s string) error {
	u, err := url.Parse(s)
	if err != nil {
		return err
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return fmt.Errorf("%q must start with http:// or https://", s)
	}
	if u.Host == "" {
		return fmt.Errorf("%q has no host", s)
	}
	if u.Scheme+"://"+u.Host != s {
		return fmt.Errorf("%q must be an origin without a path, such as %q", s, u.Scheme+"://"+u.Host)
	}
	return nil
}
